    (S ioc regb cfgb lo shi spa ff fp : Z) (xs2 xs3 xs7 xs9 errv : word) (p16 p24 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a5 a6 a7 t3 t4 t5 t6 m' j222,
    ms' = MS (mkR (Z_to_bv 64 P_A_SC_CG3R) (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa)
                  (wz cfgb) (wz AL_STR_SCHEDULER) (wz (akey_lit KLocking)) (wz 1) (wz 0) a5 a6 a7
                  xs2 xs3 (Z_to_bv 64 S) (Z_to_bv 64 (Z.shiftr (ioc + 8) 3 + 2147450880)) (Z_to_bv 64 (S + 49)) xs7
                  (Z_to_bv 64 (ioc + 8)) xs9 (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) t3 t4 t5 t6)
             F (Z_to_bv 64 P_A_CONFIG_GET_BOOL) fc None m' (seg_rom bsegs)
    /\ munch (sc_W3 lo spa S regb) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
