(* [comment removed for export] *)
Definition scU4_post (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32) (LB : list block) (LF : list fframe)
    (S ioc regb cfgb lo shi spa ff fp : Z) (xs2 xs3 xs7 errv : word) (p16 p24 : list byte) (cs : list cell) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR (Z_to_bv 64 P_A_SC_U3B) (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa)
                  (wz cfgb) (wz AL_STR_SCHEDULER) (wz (akey_lit KSpin)) (wz 0) (wz 0) a5 a6 a7
                  xs2 xs3 (Z_to_bv 64 S) (Z_to_bv 64 (Z.shiftr (ioc + 8) 3 + 2147450880)) (wz 1) xs7
                  (Z_to_bv 64 (ioc + 8)) (Z_to_bv 64 (S + 56)) (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) t3 t4 t5 t6)
             F (Z_to_bv 64 P_A_CONFIG_GET_INT) fc None m' (seg_rom bsegs)
    /\ munch (sc_W3 lo spa S regb) m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo spa
    /\ rw_cells bsegs m' spa (sc_loc p16 p24 ff)
    /\ rw_cells bsegs m' S cs
    /\ addressable m' S NEWSZ_SCH
    /\ asc_inv LB m' ioc regb cfgb errv
    /\ as_RFS H ((3, ff, fp) :: LF) m' /\ ACONST m' /\ stack0 m' lo shi.

(* [comment removed for export] *)
Lemma sc_U4 : forall (LB : list block) (LF : list fframe) (S ioc regb cfgb lo shi spa ff fp : Z) (sp tp : word) (errv : word)
    (p16 p24 : list byte) (cs : list cell) (m : mem)
    (rax gp t0 t1 t2 a1 a2 a3 a4 a5 a6 a7 xs2 xs3 xs6 xs7 xs9 t3 t4 t5 t6 : word) (F : bvmap 5 word) (fc : bv 32),
  rw_cells bsegs m spa (sc_loc p16 p24 ff) ->
  rw_cells bsegs m S cs -> Z.of_nat (cells_size cs) = 272 -> addressable m S NEWSZ_SCH ->
  stk bsegs m lo spa -> mem_inv bsegs m ->
  asc_inv LB m ioc regb cfgb errv ->
  as_RFS H ((3, ff, fp) :: LF) m -> ACONST m -> stack0 m lo shi ->
  sc_side H LB LF S ioc regb cfgb lo shi spa ff fp sp tp ->
  evt bsegs (scU4_post sp gp tp F fc LB LF S ioc regb cfgb lo shi spa ff fp xs2 xs3 xs7 errv p16 p24 cs m)
    (MS (mkR rax (Z_to_bv 64 spa) gp tp t0 t1 t2 sp (Z_to_bv 64 spa) (wz 1) a1 a2 a3 a4 a5 a6 a7
             xs2 xs3 (Z_to_bv 64 S) (Z_to_bv 64 (Z.shiftr (ioc + 8) 3 + 2147450880)) xs6 xs7
             (Z_to_bv 64 (ioc + 8)) xs9 (Z_to_bv 64 ff) (Z_to_bv 64 2147450880) t3 t4 t5 t6)
